<?php
$lastOnline=$PCC->columnExists('users','last_online');$cols='id,username,look,rank,online,account_created'.($lastOnline?',last_online':',NULL last_online');$rows=$DB->PreparedAll('SELECT '.$cols.' FROM users WHERE rank>=3 ORDER BY rank DESC,username ASC');
?>
<section class="pcc-panel"><div class="pcc-panel-head"><div><h2>Équipe ParadiseRP</h2><p>Ranks Habbo conservés comme source d’identité staff.</p></div><span class="pcc-badge success"><?php echo $number(count($rows));?> MEMBRES</span></div><div class="pcc-table-wrap"><table class="pcc-table"><thead><tr><th>Staff</th><th>Rank</th><th>Rôle admin</th><th>Statut</th><th>Création compte</th><th>Dernière connexion</th><th>Permissions</th></tr></thead><tbody><?php foreach($rows as $r):$role=$PCC->roleName($r['rank']);$caps=array();foreach($PCC->capabilityMap() as $cap=>$min)if((int)$r['rank']>=(int)$min)$caps[]=$cap;?><tr><td><div class="pcc-user-cell"><img class="pcc-table-avatar" src="<?php echo $h($PCC->avatarUrl($r['look'],'s'));?>" alt=""><span><strong><?php echo $h($r['username']);?></strong><small class="pcc-subline">#<?php echo (int)$r['id'];?></small></span></div></td><td><?php echo (int)$r['rank'];?></td><td><span class="pcc-badge"><?php echo $h($role);?></span></td><td><span class="pcc-badge <?php echo (int)$r['online']===1?'success':'';?>"><?php echo (int)$r['online']===1?'EN LIGNE':'HORS LIGNE';?></span></td><td><?php echo $h($PCC->formatDate($r['account_created']));?></td><td><?php echo $r['last_online']?$h($PCC->formatDate($r['last_online'])):'—';?></td><td><details class="pcc-diff-details"><summary><?php echo count($caps);?> capacité(s)</summary><div class="pcc-badge-list"><?php foreach($caps as $cap):?><code><?php echo $h($cap);?></code><?php endforeach;?></div></details></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="pcc-alert info"><i class="fas fa-key"></i><div><strong>RBAC V3</strong><p>Le Control Center traduit les ranks existants en capacités. Aucune action n’est sécurisée uniquement par la visibilité d’un bouton : le contrôleur vérifie la permission côté serveur.</p></div></section>
